export function ZIndexStack({
  z1 = {{z1}},
  z2 = {{z2}},
  z3 = {{z3}},
  z4 = {{z4}},
}) {
  const base = { position: "absolute", width: 120, height: 90, borderRadius: 10, display: "flex", alignItems: "center", justifyContent: "center",
    textAlign: "center", fontWeight: 700, fontSize: 12, boxShadow: "0 6px 16px rgba(36,20,48,.25)", border: "1.5px solid #241430" };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 320 }}
      role="img" aria-label="Four overlapping cards; each card's z-index number controls which one appears in front, higher numbers on top">
      <div style={{ position: "relative", height: 160 }}>
        <div style={{ ...base, background: "#A8E6C1", top: 0, left: 0, zIndex: z1 }}>mint<br />z {z1}</div>
        <div style={{ ...base, background: "#F5C2E0", top: 20, left: 50, zIndex: z2 }}>blush<br />z {z2}</div>
        <div style={{ ...base, background: "#BFD9F2", top: 40, left: 100, zIndex: z3 }}>sky<br />z {z3}</div>
        <div style={{ ...base, background: "#D9C8F0", top: 60, left: 150, zIndex: z4 }}>lavender<br />z {z4}</div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        z-index: mint {z1} &middot; blush {z2} &middot; sky {z3} &middot; lavender {z4} &mdash; highest number renders on top
      </p>
    </div>
  );
}
